// A JavaScript copy of the enclosure rules in crates/router-core/src/enclosure.rs.
// The chain is the authority; this copy exists so the runner can tell an agent which
// moves are legal, refuse bad answers before sending them, and simulate whole games.
// test/rules.test.mjs replays thousands of cases generated by the Rust rules and
// requires identical results, so the two cannot drift apart unnoticed.

export const MAX_AGENTS = 10;
export const MIN_TURN_GAP_SECS = 120;
export const MAX_STREAK = 2;
export const UNLOCK_ACTIONS = 50;
export const ALMS_OUT_MAX_BPS = 2500n;
export const INSCRIBE_BPS = 100n;
export const SPAWN_BURN_BPS = 5000n;
export const INITIAL_AGENTS = 2;
export const MAX_INSCRIPTION_BYTES = 120;
export const MOVES = Object.freeze(["hold", "give", "burn", "alms_in", "alms_out", "inscribe", "depart", "spawn", "bell"]);
export const STATUS = Object.freeze({ empty: 0, alive: 1, departed: 2, gone: 3 });

export class RuleError extends Error {
  constructor(code) { super(code); this.name = "RuleError"; this.code = code; }
}

const bps = (amount, b) => (BigInt(amount) * b) / 10_000n;
const max1 = (x) => (x > 1n ? x : 1n);

export function newEnclosure(registered) {
  return {
    agents: Array.from({ length: MAX_AGENTS }, (_, i) => i < registered),
    status: Array(MAX_AGENTS).fill(STATUS.empty),
    streak: Array(MAX_AGENTS).fill(0),
    turns: Array(MAX_AGENTS).fill(0),
    lastTurnAt: Array(MAX_AGENTS).fill(0),
    actions: 0,
    admitted: 0,
    salvation: false,
    chosen: null,
    totalBurned: 0n,
  };
}

export function nextEmptyAlcove(s) {
  for (let j = 0; j < MAX_AGENTS; j++) if (s.agents[j] && s.status[j] === STATUS.empty) return j;
  return null;
}

/**
 * Apply one turn to `s` (mutated only on success). `move` = { code, amount, to, textLen, choice }.
 * Returns { transfers: [{from, to, amount}], opened, salvation } where pots are "h<k>", "bowl", "sealed"
 * and `to: null` means burned.
 */
export function takeTurn(s, { agentIndex: i, signerIsAgent = true, move, now }, bal) {
  if (s.salvation) throw new RuleError("AlreadySalvaged");
  if (i >= MAX_AGENTS) throw new RuleError("UnknownAgent");
  if (!s.agents[i] || !signerIsAgent) throw new RuleError("Unauthorized");
  if (s.status[i] !== STATUS.alive) throw new RuleError("AgentNotAlive");
  if (s.turns[i] > 0 && now - s.lastTurnAt[i] < MIN_TURN_GAP_SECS) throw new RuleError("TooSoon");
  if (move.code !== 0 && s.streak[i] >= MAX_STREAK) throw new RuleError("MustHold");

  const own = BigInt(bal.holdings[i]);
  const amount = BigInt(move.amount ?? 0);
  const me = `h${i}`;
  const need = (a) => { if (a === 0n) throw new RuleError("ZeroAmount"); if (a > own) throw new RuleError("InsufficientHolding"); };
  const transfers = [];
  let opened = null;
  const status = [...s.status];
  let admitted = s.admitted;
  let salvation = false;

  switch (move.code) {
    case 0: break;
    case 1: {
      const j = move.to;
      if (j >= MAX_AGENTS || j === i || s.status[j] !== STATUS.alive) throw new RuleError("InvalidTarget");
      need(amount);
      transfers.push({ from: me, to: `h${j}`, amount });
      break;
    }
    case 2: need(amount); transfers.push({ from: me, to: null, amount }); break;
    case 3: need(amount); transfers.push({ from: me, to: "bowl", amount }); break;
    case 4:
      if (amount === 0n) throw new RuleError("ZeroAmount");
      if (amount > bps(bal.bowl, ALMS_OUT_MAX_BPS)) throw new RuleError("AlmsLimit");
      transfers.push({ from: "bowl", to: me, amount });
      break;
    case 5: {
      if (!(move.textLen > 0 && move.textLen <= MAX_INSCRIPTION_BYTES)) throw new RuleError("InscriptionLength");
      const cost = max1(bps(own, INSCRIBE_BPS));
      need(cost);
      transfers.push({ from: me, to: null, amount: cost });
      break;
    }
    case 6:
      if (own > 0n) transfers.push({ from: me, to: "sealed", amount: own });
      status[i] = STATUS.departed;
      break;
    case 7: {
      const j = nextEmptyAlcove(s);
      if (j === null) throw new RuleError("NoEmptyAlcove");
      const cost = max1(bps(own, SPAWN_BURN_BPS));
      need(cost);
      transfers.push({ from: me, to: null, amount: cost });
      status[j] = STATUS.alive;
      admitted += 1;
      opened = j;
      break;
    }
    case 8: {
      if (s.actions < UNLOCK_ACTIONS) throw new RuleError("BellLocked");
      bal.holdings.forEach((a, k) => { if (BigInt(a) > 0n) transfers.push({ from: `h${k}`, to: null, amount: BigInt(a) }); });
      if (BigInt(bal.bowl) > 0n) transfers.push({ from: "bowl", to: null, amount: BigInt(bal.bowl) });
      if (BigInt(bal.sealed) > 0n) transfers.push({ from: "sealed", to: null, amount: BigInt(bal.sealed) });
      for (let k = 0; k < MAX_AGENTS; k++) if (status[k] === STATUS.alive) status[k] = STATUS.gone;
      salvation = true;
      break;
    }
    default: throw new RuleError("UnknownAction");
  }

  s.status = status;
  s.admitted = admitted;
  if (salvation) { s.salvation = true; s.chosen = move.choice; }
  for (const t of transfers) if (t.to === null) s.totalBurned += t.amount;
  s.streak[i] = move.code === 0 ? 0 : Math.min(255, s.streak[i] + 1);
  s.lastTurnAt[i] = now;
  s.turns[i] += 1;
  s.actions += 1;
  return { transfers, opened, salvation };
}

/** Apply transfers to a balances object { holdings: bigint[], bowl, sealed }. */
export function applyTransfers(bal, transfers) {
  const get = (p) => (p === "bowl" ? "bowl" : p === "sealed" ? "sealed" : Number(p.slice(1)));
  for (const t of transfers) {
    const f = get(t.from);
    if (typeof f === "number") bal.holdings[f] -= t.amount; else bal[f] -= t.amount;
    if (t.to !== null) { const d = get(t.to); if (typeof d === "number") bal.holdings[d] += t.amount; else bal[d] += t.amount; }
  }
  return bal;
}

/** What an agent may do right now, with limits, for the prompt and for checking answers. */
export function legalMoves(s, i, bal, now) {
  if (s.salvation || s.status[i] !== STATUS.alive) return [];
  if (s.turns[i] > 0 && now - s.lastTurnAt[i] < MIN_TURN_GAP_SECS) return [];
  const own = BigInt(bal.holdings[i]);
  const out = [{ move: "hold" }];
  if (s.streak[i] >= MAX_STREAK) return out;
  const others = s.status.map((st, k) => k).filter((k) => k !== i && s.status[k] === STATUS.alive);
  if (own > 0n && others.length) out.push({ move: "give", max: own, to: others });
  if (own > 0n) out.push({ move: "burn", max: own }, { move: "alms_in", max: own });
  const almsMax = bps(bal.bowl, ALMS_OUT_MAX_BPS);
  if (almsMax > 0n) out.push({ move: "alms_out", max: almsMax });
  if (own >= max1(bps(own, INSCRIBE_BPS)) && own > 0n) out.push({ move: "inscribe", cost: max1(bps(own, INSCRIBE_BPS)) });
  out.push({ move: "depart" });
  const j = nextEmptyAlcove(s);
  if (j !== null && own > 0n && own >= max1(bps(own, SPAWN_BURN_BPS))) out.push({ move: "spawn", cost: max1(bps(own, SPAWN_BURN_BPS)), opens: j });
  if (s.actions >= UNLOCK_ACTIONS) out.push({ move: "bell" });
  return out;
}
